<?php use App\Core\Csrf;use App\Core\Format;?>
<div class="module-page"><div class="module-hero"><div><h1>Editar usuário</h1><p>Altere grupo, escopo e unidade. Mudanças de permissão invalidam as sessões abertas do usuário.</p></div><a class="btn neutral" href="/admin/usuarios">← Voltar</a></div><?php if(!empty($erro)):?><div class="flash error"><?=Format::h($erro)?></div><?php endif;?><?php if(!empty($ok)):?><div class="flash ok"><?=Format::h($ok)?></div><?php endif;?>
<section class="card config-card"><form method="post" action="/admin/usuarios/<?=$usuario['id']?>" class="production-form" id="userEditForm"><input type="hidden" name="_token" value="<?=Format::h(Csrf::token())?>"><label>Nome<input name="nome" value="<?=Format::h($usuario['nome'])?>" required></label><label>E-mail<input value="<?=Format::h($usuario['email'])?>" readonly></label><label>Grupo<select name="grupo" id="editUserGroup"><?php foreach(['ADMINISTRADOR','GESTOR','USUARIO'] as$g):?><option <?=$usuario['grupo']===$g?'selected':''?>><?=$g?></option><?php endforeach;?></select></label><label>Município<select name="municipio_id" id="editUserMunicipio"><option value="">Plataforma</option><?php foreach($municipios as$m):?><option value="<?=$m['id']?>" <?=(int)$usuario['municipio_id']===(int)$m['id']?'selected':''?>><?=Format::h($m['nome'].' - '.$m['uf'])?></option><?php endforeach;?></select></label><label>Secretaria<select name="secretaria_id" id="editUserSecretaria"><option value="">Sem secretaria</option><?php foreach($secretarias as$s):?><option value="<?=$s['id']?>" data-municipio="<?=$s['municipio_id']?>" <?=(int)$usuario['secretaria_id']===(int)$s['id']?'selected':''?>><?=Format::h(($s['sigla']?$s['sigla'].' — ':'').$s['nome'])?></option><?php endforeach;?></select></label><label>Departamento<select name="departamento_id" id="editUserDepartamento"><option value="">Toda a secretaria</option><?php foreach($departamentos as$d):?><option value="<?=$d['id']?>" data-municipio="<?=$d['municipio_id']?>" data-secretaria="<?=$d['secretaria_id']?>" <?=(int)$usuario['departamento_id']===(int)$d['id']?'selected':''?>><?=Format::h(($d['sigla']?$d['sigla'].' — ':'').$d['nome'])?></option><?php endforeach;?></select></label><label class="check-line"><input type="checkbox" name="administrador_plataforma" value="1" id="editPlatformAdmin" <?=$usuario['administrador_plataforma']?'checked':''?>> Administrador da plataforma Stratelli</label><div class="security-change-warning">⚠ Alterações de grupo, município, secretaria ou departamento encerram automaticamente sessões antigas deste usuário.</div><button class="btn primary">Salvar alterações</button></form></section>
<section class="card config-card admin-password-card"><div class="card-title"><h2>🔐 Definir nova senha</h2><p>Como administrador da plataforma, você pode definir uma nova senha para este usuário. A senha atual nunca é exibida.</p></div><form method="post" action="/admin/usuarios/<?=$usuario['id']?>/senha" class="production-form" id="adminPasswordForm"><input type="hidden" name="_token" value="<?=Format::h(Csrf::token())?>"><label>Nova senha<input id="adminNovaSenha" type="password" name="nova_senha" minlength="10" autocomplete="new-password" required placeholder="Mínimo de 10 caracteres"></label><label>Confirmar nova senha<input id="adminConfirmacaoSenha" type="password" name="confirmacao_senha" minlength="10" autocomplete="new-password" required placeholder="Digite novamente a nova senha"></label><small id="adminPasswordMatch" class="password-match-message">As duas senhas devem ser idênticas.</small><div class="security-change-warning">⚠ Ao definir uma nova senha, todas as sessões abertas deste usuário serão invalidadas e ele precisará entrar novamente com a nova senha.</div><button class="btn primary" type="submit">Definir nova senha</button></form></section></div>
<script>(function(){const m=document.getElementById('editUserMunicipio'),s=document.getElementById('editUserSecretaria'),d=document.getElementById('editUserDepartamento'),g=document.getElementById('editUserGroup'),p=document.getElementById('editPlatformAdmin');function sync(){const platform=p.checked;s.disabled=platform||g.value!=='USUARIO';d.disabled=platform||g.value!=='USUARIO';m.disabled=platform;[...s.options].forEach((o,i)=>{if(i)o.hidden=!!m.value&&o.dataset.municipio!==m.value});[...d.options].forEach((o,i)=>{if(i)o.hidden=(!!m.value&&o.dataset.municipio!==m.value)||(!!s.value&&o.dataset.secretaria!==s.value)});}m.onchange=sync;s.onchange=sync;g.onchange=sync;p.onchange=sync;sync();})();</script>
